-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('3669c1fd-0ca5-5ade-96c9-5cc4c3191f7d'::uuid, 'd4acf12a-266d-59bc-a649-a116818ce60a'::uuid, 'Comment la poésie médiévale était-elle d’abord diffusée ?', 'mcq', '["Chantée, accompagnée de musique","Imprimée en recueils","Lue en silence","Affichée dans les églises"]'::jsonb, 0, 'Troubadours et trouvères sont autant musiciens que poètes.', 1),
    ('63b16c8c-e03f-5d91-88c7-a3c1db387a09'::uuid, 'd4acf12a-266d-59bc-a649-a116818ce60a'::uuid, 'Qu’est-ce que l’amour courtois ?', 'mcq', '["Le service amoureux d’un chevalier envers une dame idéalisée","Un mariage arrangé par le roi","L’amour entre paysans","Une forme de poésie religieuse"]'::jsonb, 0, 'La dame est inaccessible : c’est le désir, pas sa satisfaction, qui fait le poème.', 2),
    ('6801b585-3616-5fba-a815-0bdc957b5dc9'::uuid, 'd4acf12a-266d-59bc-a649-a116818ce60a'::uuid, 'Quel poète du XVe siècle écrit la faim, la prison et la mort ?', 'mcq', '["François Villon","Pierre de Ronsard","Joachim Du Bellay","Jean de La Fontaine"]'::jsonb, 0, 'Il rompt avec la poésie courtoise par sa langue directe.', 3),
    ('b4db203e-a733-5162-918c-58c0a040683e'::uuid, 'd4acf12a-266d-59bc-a649-a116818ce60a'::uuid, 'Que revendique la Pléiade au XVIe siècle ?', 'mcq', '["Écrire une poésie savante en français plutôt qu’en latin","Revenir au latin","Supprimer la rime","Abandonner le sonnet"]'::jsonb, 0, 'C’est le programme de la « Défense et illustration de la langue française ».', 4),
    ('743c32e7-f75d-5582-996d-3dd62c10e99a'::uuid, 'd4acf12a-266d-59bc-a649-a116818ce60a'::uuid, 'D’où vient la forme du sonnet ?', 'mcq', '["D’Italie","D’Angleterre","D’Espagne","De Grèce"]'::jsonb, 0, 'Pétrarque en fait le modèle que la Pléiade importe en France.', 5),
    ('71ec1dc1-5a1d-591c-9415-5b89c4cb4ca9'::uuid, 'd4acf12a-266d-59bc-a649-a116818ce60a'::uuid, 'Quel genre poétique La Fontaine porte-t-il au premier plan au XVIIe siècle ?', 'mcq', '["La fable","L’ode","La ballade","Le calligramme"]'::jsonb, 0, 'Elle fait entrer le récit et la satire dans le vers.', 6),
    ('85c974a1-8abc-55cd-8d1a-fe04221aee5f'::uuid, 'd4acf12a-266d-59bc-a649-a116818ce60a'::uuid, 'Au XVIIIe siècle, la poésie est surtout mise au service des idées.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le siècle des Lumières préfère l’argumentation au lyrisme.', 7),
    ('82d44aff-6437-5dde-8103-0feb10a33403'::uuid, 'd4acf12a-266d-59bc-a649-a116818ce60a'::uuid, 'Quels sont les trois grands chantiers du poète, quel que soit le siècle ?', 'mcq', '["Le rythme, le son et l’image","La grammaire, l’orthographe et le style","L’intrigue, les personnages et le décor","La thèse, l’argument et l’exemple"]'::jsonb, 0, 'Vers et strophe, rime et sonorités, comparaison et métaphore.', 8),
    ('f76e3531-ec1a-5876-abb5-c4c8ff0a7c1d'::uuid, '1851514e-4e55-5fd3-bfec-361766a3738a'::uuid, 'Combien de syllabes compte un alexandrin ?', 'mcq', '["12","10","8","14"]'::jsonb, 0, 'Il se coupe souvent en deux hémistiches de six syllabes.', 1),
    ('0d5c28d0-1bb6-594b-b02c-3511fab6a20a'::uuid, '1851514e-4e55-5fd3-bfec-361766a3738a'::uuid, 'Qu’est-ce que la césure ?', 'mcq', '["La coupe qui sépare un vers en deux hémistiches","La rime finale","Le passage à la strophe suivante","Le silence entre deux poèmes"]'::jsonb, 0, 'Dans l’alexandrin classique, elle tombe après la sixième syllabe.', 2),
    ('4a66f765-c552-59d4-9e24-b106ff0bf944'::uuid, '1851514e-4e55-5fd3-bfec-361766a3738a'::uuid, 'Qu’appelle-t-on diérèse ?', 'mcq', '["Prononcer en deux syllabes deux voyelles voisines","Supprimer un e muet","Répéter une consonne","Couper un vers en deux"]'::jsonb, 0, 'Li-on compte alors deux syllabes au lieu d’une.', 3),
    ('d4857229-f375-5be2-9551-39fb3aeb5d15'::uuid, '1851514e-4e55-5fd3-bfec-361766a3738a'::uuid, 'Comment se nomme le schéma de rimes ABBA ?', 'mcq', '["Rimes embrassées","Rimes croisées","Rimes suivies","Rimes plates"]'::jsonb, 0, 'Les rimes croisées sont en ABAB, les suivies en AABB.', 4),
    ('cf0fb31c-29af-56ca-abe9-1eedfe1e50cc'::uuid, '1851514e-4e55-5fd3-bfec-361766a3738a'::uuid, 'De quoi est composé un sonnet ?', 'mcq', '["Deux quatrains et deux tercets","Trois quatrains et un distique","Quatre tercets","Deux sizains"]'::jsonb, 0, 'Soit quatorze vers au total.', 5),
    ('53303386-b1bc-5f07-9665-2cbf31a788bd'::uuid, '1851514e-4e55-5fd3-bfec-361766a3738a'::uuid, 'Qu’est-ce qu’un rejet ?', 'mcq', '["Un fragment de phrase qui déborde au début du vers suivant","Une rime pauvre","Un vers supprimé","Une strophe isolée"]'::jsonb, 0, 'Le débordement met le mot rejeté en relief.', 6),
    ('9a48dc30-119f-5970-9bc3-9c1cb7d7c114'::uuid, '1851514e-4e55-5fd3-bfec-361766a3738a'::uuid, 'Une allitération répète une voyelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle répète une consonne ; la répétition d’une voyelle est une assonance.', 7),
    ('9c6fa1d1-12f0-56cc-931c-146586af6195'::uuid, '1851514e-4e55-5fd3-bfec-361766a3738a'::uuid, 'Qu’est-ce qu’un oxymore ?', 'mcq', '["L’association de deux mots de sens contraire","Une exagération","Une comparaison sans outil","Une répétition en début de vers"]'::jsonb, 0, 'Comme « une clarté obscure ».', 8),
    ('f83f0d0a-1a66-5f3f-b26c-69e7263e8c86'::uuid, '198e0bdd-5ba2-5bb5-b717-ad523aa9b73b'::uuid, 'Qu’est-ce qu’une branche du Roman de Renart ?', 'mcq', '["Un récit indépendant qui compose l’ensemble","Un chapitre de roman moderne","Une famille de personnages","Un épisode musical"]'::jsonb, 0, 'Les branches sont écrites par des auteurs différents sur près d’un siècle.', 1),
    ('870a4ee3-1950-55eb-b228-c38d77689ede'::uuid, '198e0bdd-5ba2-5bb5-b717-ad523aa9b73b'::uuid, 'Quels genres le Roman de Renart parodie-t-il ?', 'mcq', '["La chanson de geste et le roman courtois","La tragédie et la comédie","Le sonnet et l’ode","L’autobiographie et le journal"]'::jsonb, 0, 'Il imite leurs codes pour en faire rire.', 2),
    ('7a4f122b-f5b1-5f87-b7a3-f6fd7c6d592b'::uuid, '198e0bdd-5ba2-5bb5-b717-ad523aa9b73b'::uuid, 'Quel animal est le roi dans le Roman de Renart ?', 'mcq', '["Noble le lion","Ysengrin le loup","Brun l’ours","Tibert le chat"]'::jsonb, 0, 'La cour reproduit la hiérarchie féodale.', 3),
    ('21739dea-4fbb-5e7e-a92d-6c2c6841f4a4'::uuid, '198e0bdd-5ba2-5bb5-b717-ad523aa9b73b'::uuid, 'Qui est le rival principal de Renart ?', 'mcq', '["Ysengrin le loup","Chantecler le coq","Tibert le chat","Noble le lion"]'::jsonb, 0, 'Le grand baron brutal, toujours victime de la ruse du goupil.', 4),
    ('4664fdaf-23f0-5dea-bc56-9882e67a3fec'::uuid, '198e0bdd-5ba2-5bb5-b717-ad523aa9b73b'::uuid, 'Quelle trace le personnage a-t-il laissée dans la langue française ?', 'mcq', '["Son nom propre a remplacé le mot goupil","Il a donné son nom au loup","Il a créé le mot roman","Il a fait disparaître le mot lion"]'::jsonb, 0, 'C’est un cas rare de nom propre devenu nom commun.', 5),
    ('b1586d84-8d28-50e3-9cfe-28e0fca1dcd6'::uuid, '198e0bdd-5ba2-5bb5-b717-ad523aa9b73b'::uuid, 'Renart est un héros exemplaire et vertueux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est menteur, voleur et cruel : la satire ne propose pas de modèle.', 6),
    ('bc82b74d-3748-5c2a-85fd-a805a8306b38'::uuid, '198e0bdd-5ba2-5bb5-b717-ad523aa9b73b'::uuid, 'Que vise la satire du Roman de Renart ?', 'mcq', '["Les puissants, la justice féodale et l’hypocrisie religieuse","Les paysans","Les femmes de la cour","Les auteurs de romans courtois"]'::jsonb, 0, 'Le rire sert de couverture à la critique sociale.', 7),
    ('2bd0f3d0-7c6d-50e0-b116-245eed4eb53a'::uuid, '198e0bdd-5ba2-5bb5-b717-ad523aa9b73b'::uuid, 'Pourquoi faire parler des animaux plutôt que des hommes ?', 'mcq', '["Le masque animal permet de critiquer sans nommer directement","Parce que les animaux étaient à la mode","Pour éviter d’écrire des dialogues","Pour respecter les règles du roman"]'::jsonb, 0, 'La fable utilisera plus tard exactement le même procédé.', 8),
    ('9caaa30a-e557-5219-a91d-02abbc87166f'::uuid, '72d2fc0e-a354-5589-94fc-00a7f335d24a'::uuid, 'Comment se répartissent les 14 vers d’un sonnet ?', 'mcq', '["Deux quatrains puis deux tercets","Trois quatrains puis un distique","Deux sizains puis un distique","Quatorze vers sans strophes"]'::jsonb, 0, 'La bascule se fait au passage des quatrains aux tercets.', 1),
    ('f42bd1d1-fb1f-59e6-a7d6-4dc6ce62408b'::uuid, '72d2fc0e-a354-5589-94fc-00a7f335d24a'::uuid, 'Comment appelle-t-on le dernier vers du sonnet, qui condense le propos ?', 'mcq', '["La chute","La césure","L’envoi","Le refrain"]'::jsonb, 0, 'Elle donne au sonnet sa forme de raisonnement.', 2),
    ('d3a97424-1553-533b-a220-2d80a9286a9c'::uuid, '72d2fc0e-a354-5589-94fc-00a7f335d24a'::uuid, 'Dans quel recueil Du Bellay écrit-il « Heureux qui, comme Ulysse » ?', 'mcq', '["Les Regrets","Les Amours","Les Antiquités de Rome","Les Odes"]'::jsonb, 0, 'Un recueil né de son séjour à Rome.', 3),
    ('48ac9454-7703-5669-81df-352af1732a27'::uuid, '72d2fc0e-a354-5589-94fc-00a7f335d24a'::uuid, 'Que dit ce sonnet de Du Bellay ?', 'mcq', '["Qu’il préfère son village natal à la grandeur de Rome","Qu’il veut rester à Rome","Qu’il rêve de partir en Grèce","Qu’il renonce à la poésie"]'::jsonb, 0, 'Le voyage antique sert à dire le mal du pays.', 4),
    ('7baee0c7-2a40-5c0b-96d1-78214ac2dc91'::uuid, '72d2fc0e-a354-5589-94fc-00a7f335d24a'::uuid, 'Que signifie carpe diem ?', 'mcq', '["Cueille le jour, profite du présent","Souviens-toi que tu mourras","Connais-toi toi-même","Rien de trop"]'::jsonb, 0, 'La formule vient d’Horace ; Ronsard en fait un art d’aimer.', 5),
    ('9760e618-8a96-5469-bef2-b8b8216d58ad'::uuid, '72d2fc0e-a354-5589-94fc-00a7f335d24a'::uuid, 'Sur quelle figure repose « Mignonne, allons voir si la rose » ?', 'mcq', '["Une comparaison entre la rose fanée et la jeunesse qui passe","Une personnification du temps","Une allitération en r","Une litote"]'::jsonb, 0, 'La fleur d’un jour donne sa leçon au poème.', 6),
    ('f7e8cc02-f5e5-575f-b807-b970291fe1f8'::uuid, '72d2fc0e-a354-5589-94fc-00a7f335d24a'::uuid, 'Dans le sonnet de la Pléiade, l’animal est surtout un support d’image.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cerf blessé, oiseau en cage, biche insaisissable : des métaphores du désir.', 7),
    ('cc56dd8e-f94f-5106-a048-064d1faaa301'::uuid, '72d2fc0e-a354-5589-94fc-00a7f335d24a'::uuid, 'De quel poète italien viennent ces images animales du désir ?', 'mcq', '["Pétrarque","Dante","Boccace","Virgile"]'::jsonb, 0, 'Le pétrarquisme fournit à toute l’Europe son répertoire amoureux.', 8),
    ('20eb5fb8-32ec-5f82-836b-8d8266d22be5'::uuid, 'b68d206d-0095-5067-8dd2-7eda4eb20591'::uuid, 'Que signifie l’expression « la part du lion » ?', 'mcq', '["La plus grosse part, prise par le plus fort","Une part égale pour tous","Une part symbolique","La part réservée aux invités"]'::jsonb, 0, 'Elle vient des fables antiques d’Ésope.', 1),
    ('795047f1-29fa-5eab-87dd-fa439196ea4f'::uuid, 'b68d206d-0095-5067-8dd2-7eda4eb20591'::uuid, 'Que représente le lion dans le bestiaire médiéval chrétien ?', 'mcq', '["Une figure du Christ","Le diable uniquement","La paresse","La gourmandise"]'::jsonb, 0, 'Il ranime ses petits au troisième jour : l’image de la résurrection.', 2),
    ('baeace60-e6c7-5800-91bf-08a37347805e'::uuid, 'b68d206d-0095-5067-8dd2-7eda4eb20591'::uuid, 'Dans quel roman de Chrétien de Troyes un lion devient-il le compagnon du héros ?', 'mcq', '["Le Chevalier au lion (Yvain)","Perceval","Lancelot","Érec et Énide"]'::jsonb, 0, 'Le lion sauvé par Yvain lui reste fidèle.', 3),
    ('bd384481-1afd-5493-b994-bd34d577de53'::uuid, 'b68d206d-0095-5067-8dd2-7eda4eb20591'::uuid, 'Comment s’appelle le lion du Roman de Renart ?', 'mcq', '["Noble","Ysengrin","Brun","Tibert"]'::jsonb, 0, 'Un roi faible et partial, cible de la satire.', 4),
    ('e6f99e3b-6fe1-565e-9a3a-d9344301e758'::uuid, 'b68d206d-0095-5067-8dd2-7eda4eb20591'::uuid, 'Que montre « La Génisse, la Chèvre et la Brebis en société avec le Lion » ?', 'mcq', '["La loi du plus fort déguisée en contrat","La solidarité entre animaux","La récompense du travail","La supériorité de la ruse"]'::jsonb, 0, 'Le partage est décidé d’avance par celui qui a la force.', 5),
    ('df4ef14a-f166-5d1d-aef9-c5938e94a2f7'::uuid, 'b68d206d-0095-5067-8dd2-7eda4eb20591'::uuid, 'Quelle leçon tire-t-on du « Lion et le Rat » ?', 'mcq', '["On a souvent besoin d’un plus petit que soi","Il faut se méfier des faibles","La force finit toujours par gagner","Mieux vaut ne rien devoir à personne"]'::jsonb, 0, 'La fable retourne le rapport de force.', 6),
    ('ecc02ab0-a914-5f24-a535-64cf002b6cbf'::uuid, 'b68d206d-0095-5067-8dd2-7eda4eb20591'::uuid, 'Quel écrivain du XXe siècle a intitulé un roman « Le Lion » ?', 'mcq', '["Joseph Kessel","Albert Camus","André Malraux","Romain Gary"]'::jsonb, 0, 'Le roman interroge la place de l’homme face à la nature sauvage.', 7),
    ('70e8a883-ba4d-566e-bb41-90bc9018d948'::uuid, 'b68d206d-0095-5067-8dd2-7eda4eb20591'::uuid, 'Le sens d’un motif littéraire comme le lion est fixe d’une époque à l’autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Universel dans sa présence, il est pluriel dans ses valeurs.', 8),
    ('ec467ea7-aeab-5293-84c1-6b7d997a0731'::uuid, '70db68ba-a608-5c80-b788-5824be872f34'::uuid, 'Qu’est-ce qu’un apologue ?', 'mcq', '["Un récit bref qui sert une démonstration","Un poème d’amour","Une pièce en un acte","Un discours de tribunal"]'::jsonb, 0, 'La fable, le conte philosophique et la parabole en sont.', 1),
    ('14c95509-4dec-5043-891e-9cf2853bbae6'::uuid, '70db68ba-a608-5c80-b788-5824be872f34'::uuid, 'De quels deux temps la fable est-elle faite ?', 'mcq', '["Un récit et une morale","Une thèse et une antithèse","Un prologue et un épilogue","Une strophe et un refrain"]'::jsonb, 0, 'La morale peut être explicite ou implicite.', 2),
    ('6e513a9d-b383-5030-a059-a6b7f0a20c8f'::uuid, '70db68ba-a608-5c80-b788-5824be872f34'::uuid, 'Quel double effet produit l’animalisation des personnages ?', 'mcq', '["Elle plaît et elle protège l’auteur","Elle allonge le récit","Elle supprime la morale","Elle rend le texte plus difficile"]'::jsonb, 0, 'On parle d’un loup, pas d’un ministre.', 3),
    ('177f2138-fbea-55ee-bfe9-cd3f4968e161'::uuid, '70db68ba-a608-5c80-b788-5824be872f34'::uuid, 'Que dénonce le vers « Selon que vous serez puissant ou misérable » ?', 'mcq', '["L’inégalité de la justice","La pauvreté des campagnes","La guerre","L’ignorance du peuple"]'::jsonb, 0, 'La fable des Animaux malades de la peste vise les jugements de cour.', 4),
    ('e73d6afb-10ac-5e4f-a6b2-f1ba66750f17'::uuid, '70db68ba-a608-5c80-b788-5824be872f34'::uuid, 'Quelle affaire judiciaire Voltaire a-t-il combattue ?', 'mcq', '["L’affaire Calas","L’affaire Dreyfus","L’affaire du collier","L’affaire Fouquet"]'::jsonb, 0, 'Un père protestant exécuté sur des preuves inexistantes.', 5),
    ('41e5fbe7-67d0-5d69-8898-156e118c435d'::uuid, '70db68ba-a608-5c80-b788-5824be872f34'::uuid, 'Dans quel conte de Voltaire figure l’épisode du nègre de Surinam ?', 'mcq', '["Candide","Micromégas","Zadig","L’Ingénu"]'::jsonb, 0, 'Un des textes les plus durs du siècle contre l’esclavage.', 6),
    ('e4a17812-d8cb-59e9-9602-1ce639cb0790'::uuid, '70db68ba-a608-5c80-b788-5824be872f34'::uuid, 'Quel procédé partagent la fable et le conte philosophique des Lumières ?', 'mcq', '["L’ironie","La rime riche","Le monologue intérieur","Le récit à la première personne"]'::jsonb, 0, 'Dire le contraire de ce qu’on pense pour le rendre insoutenable.', 7),
    ('2f19bc4f-27b5-58d7-b2e1-c1b248692465'::uuid, '70db68ba-a608-5c80-b788-5824be872f34'::uuid, 'Les Lumières ont inventé la forme de la fable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est antique ; elles en héritent et la rechargent de leurs combats.', 8),
    ('77d0574b-1804-5224-a1f4-71779a82d4ed'::uuid, '89d9952d-d7a8-5932-b3c9-6693e2097d05'::uuid, 'Quelle différence entre convaincre et persuader ?', 'mcq', '["Convaincre s’adresse à la raison, persuader aux émotions","Convaincre s’adresse aux émotions, persuader à la raison","Les deux sont synonymes","Convaincre concerne l’oral, persuader l’écrit"]'::jsonb, 0, 'Un texte efficace combine souvent les deux.', 1),
    ('5ee9ad34-c988-5673-a598-edeffa3ad8d4'::uuid, '89d9952d-d7a8-5932-b3c9-6693e2097d05'::uuid, 'Que garantit la loi du 29 juillet 1881 ?', 'mcq', '["La liberté de la presse","La gratuité de l’école","La séparation des Églises et de l’État","Le droit de grève"]'::jsonb, 0, 'Elle fait du journal le premier média de masse.', 2),
    ('e3634fce-99a4-5a41-a706-957bf887ecad'::uuid, '89d9952d-d7a8-5932-b3c9-6693e2097d05'::uuid, 'Dans quel journal Zola publie-t-il « J’accuse…! » ?', 'mcq', '["L’Aurore","Le Figaro","Le Temps","La Presse"]'::jsonb, 0, 'En une, le 13 janvier 1898.', 3),
    ('96fad3b6-a27e-5d32-bc65-40a51316d797'::uuid, '89d9952d-d7a8-5932-b3c9-6693e2097d05'::uuid, 'À quelle affaire ce texte est-il lié ?', 'mcq', '["L’affaire Dreyfus","L’affaire Calas","L’affaire du collier","L’affaire Stavisky"]'::jsonb, 0, 'Une erreur judiciaire devenue crise politique.', 4),
    ('5d4d321b-ea93-5eda-9ada-de6d59645541'::uuid, '89d9952d-d7a8-5932-b3c9-6693e2097d05'::uuid, 'Qui publie « Le Deuxième Sexe » en 1949 ?', 'mcq', '["Simone de Beauvoir","Colette","Marguerite Duras","Louise Michel"]'::jsonb, 0, 'Un essai fondateur de la pensée féministe.', 5),
    ('50be7f46-bacd-5a5f-9234-e92b93f77f72'::uuid, '89d9952d-d7a8-5932-b3c9-6693e2097d05'::uuid, 'Qu’est-ce que la thèse d’un texte argumentatif ?', 'mcq', '["L’idée que le texte soutient","L’exemple le plus long","La conclusion du dernier paragraphe uniquement","Le sujet du texte"]'::jsonb, 0, 'Les arguments la soutiennent, les exemples l’illustrent.', 6),
    ('67127d5b-0533-573c-911e-3320280a9df0'::uuid, '89d9952d-d7a8-5932-b3c9-6693e2097d05'::uuid, 'Au XIXe siècle, écrivains et journalistes sont souvent les mêmes personnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Hugo, Zola et Sand publient dans la presse.', 7),
    ('0f092bd2-6517-55f5-874c-008fd93158f3'::uuid, '89d9952d-d7a8-5932-b3c9-6693e2097d05'::uuid, 'Quel procédé consiste à poser une question dont on attend qu’elle réponde d’elle-même ?', 'mcq', '["La question rhétorique","L’anaphore","La litote","La périphrase"]'::jsonb, 0, 'Elle fait participer le lecteur au raisonnement.', 8),
    ('8143c30c-ada3-55b8-be3c-bcd134143112'::uuid, 'be9f28b0-7f80-56e6-b562-25fad286a933'::uuid, 'Quelles sont les cinq questions de base d’un article ?', 'mcq', '["Qui, quoi, quand, où, pourquoi","Comment, combien, pourquoi, quand, qui","Où, quand, combien, à qui, pour quoi faire","Qui, comment, combien, pourquoi, où"]'::jsonb, 0, 'Souvent complétées par « comment ».', 1),
    ('a6fbb6e6-314d-50f6-bfdd-71198b182218'::uuid, 'be9f28b0-7f80-56e6-b562-25fad286a933'::uuid, 'Qu’est-ce que la pyramide inversée ?', 'mcq', '["Donner l’essentiel d’abord, les détails ensuite","Terminer par l’information principale","Alterner faits et opinions","Classer les articles par longueur"]'::jsonb, 0, 'Elle permet de couper la fin sans perdre l’essentiel.', 2),
    ('8e34a3ad-0bd7-5ea6-90ba-f4d848647c44'::uuid, 'be9f28b0-7f80-56e6-b562-25fad286a933'::uuid, 'Lequel de ces genres relève de l’opinion et non de l’information ?', 'mcq', '["L’éditorial","La brève","Le reportage","L’enquête"]'::jsonb, 0, 'Il exprime la position du journal.', 3),
    ('9ccc6e2d-c8bc-5bc6-aee3-8161bb90a8cd'::uuid, 'be9f28b0-7f80-56e6-b562-25fad286a933'::uuid, 'Qu’est-ce qu’un chapô ?', 'mcq', '["Le court texte qui résume l’article sous le titre","La première phrase de l’article","La légende d’une photo","La signature du journaliste"]'::jsonb, 0, 'L’attaque est la première phrase, la chute la dernière.', 4),
    ('c6e8d97b-1434-5889-93eb-e32dda1b506b'::uuid, 'be9f28b0-7f80-56e6-b562-25fad286a933'::uuid, 'Que fixe la Charte de Munich de 1971 ?', 'mcq', '["Les devoirs et les droits des journalistes","Le prix des journaux","La formation des rédacteurs","Le statut des photographes"]'::jsonb, 0, 'Vérité, vérification, rectification, protection des sources.', 5),
    ('953efbab-2a14-53d1-9ef0-e7cdc64ba5d5'::uuid, 'be9f28b0-7f80-56e6-b562-25fad286a933'::uuid, 'Que signifie recouper une information ?', 'mcq', '["La confirmer par au moins deux sources indépendantes","La raccourcir","La publier en plusieurs parties","La traduire"]'::jsonb, 0, 'Une source unique ne suffit jamais.', 6),
    ('3254c73b-c6d4-5a5b-99c6-dbfb7bae7c63'::uuid, 'be9f28b0-7f80-56e6-b562-25fad286a933'::uuid, 'Une opinion se vérifie de la même manière qu’un fait.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un fait se vérifie, une opinion se discute.', 7),
    ('f6ab2a0d-9b4f-5abb-8fb8-886662f01040'::uuid, 'be9f28b0-7f80-56e6-b562-25fad286a933'::uuid, 'Quel réflexe permet de dater et situer une photo suspecte ?', 'mcq', '["La recherche d’image inversée","La lecture des commentaires","Le comptage des partages","La vérification de l’orthographe"]'::jsonb, 0, 'Elle retrouve les publications antérieures de la même image.', 8),
    ('554809bd-7112-5b8d-a1d2-81c044ecd2de'::uuid, '7bb43133-61e2-5c03-971d-8c1643b82111'::uuid, 'Quelle invention économique Girardin introduit-il en 1836 ?', 'mcq', '["Financer le journal par la publicité pour en baisser le prix","Vendre le journal par abonnement uniquement","Supprimer les illustrations","Imprimer sur du papier de luxe"]'::jsonb, 0, 'La Presse coûte deux fois moins cher que ses concurrents.', 1),
    ('84d50c1b-bfb9-5b36-a65b-dc40331b1622'::uuid, '7bb43133-61e2-5c03-971d-8c1643b82111'::uuid, 'Qu’est-ce qu’un roman-feuilleton ?', 'mcq', '["Un roman publié en épisodes dans un journal","Un roman écrit par plusieurs auteurs","Un roman illustré","Un roman court en un seul numéro"]'::jsonb, 0, 'Il se termine sur un suspense pour faire acheter le numéro suivant.', 2),
    ('33b67760-5a45-5d39-bba7-cbd8f4f88e73'::uuid, '7bb43133-61e2-5c03-971d-8c1643b82111'::uuid, 'Quel auteur publie « Les Mystères de Paris » en feuilleton ?', 'mcq', '["Eugène Sue","Alexandre Dumas","Émile Zola","Honoré de Balzac"]'::jsonb, 0, 'Un immense succès populaire des années 1840.', 3),
    ('57dce85a-2e71-58c0-874e-ecd6f581cdcf'::uuid, '7bb43133-61e2-5c03-971d-8c1643b82111'::uuid, 'Que garantissent les lois Ferry de 1881-1882 ?', 'mcq', '["Une école gratuite, laïque et obligatoire","La liberté de la presse","Le droit de vote des femmes","La liberté syndicale"]'::jsonb, 0, 'L’alphabétisation crée le public des journaux.', 4),
    ('87c6e9bc-70d2-55f3-90bb-77aefde69556'::uuid, '7bb43133-61e2-5c03-971d-8c1643b82111'::uuid, 'Quelle technique permet la diffusion rapide des dépêches au XIXe siècle ?', 'mcq', '["Le télégraphe","Le téléphone portable","La radio","La photographie"]'::jsonb, 0, 'Relayé par le chemin de fer pour la distribution.', 5),
    ('4406e2c7-41d2-550c-8d6c-9d7f94e95fa7'::uuid, '7bb43133-61e2-5c03-971d-8c1643b82111'::uuid, 'Contre quoi Victor Hugo mène-t-il campagne dans la presse ?', 'mcq', '["La peine de mort et le coup d’État de 1851","La liberté de la presse","L’école gratuite","Le roman-feuilleton"]'::jsonb, 0, 'Il paiera son opposition de dix-neuf ans d’exil.', 6),
    ('94033c0e-52b8-5325-bfbf-139d9fe8b8bb'::uuid, '7bb43133-61e2-5c03-971d-8c1643b82111'::uuid, 'La loi de 1881 supprime toute sanction contre les journaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle protège la liberté mais punit notamment la diffamation.', 7),
    ('13d0832d-e92d-5b12-9fc1-8a819d456875'::uuid, '7bb43133-61e2-5c03-971d-8c1643b82111'::uuid, 'Quel dessinateur incarne la caricature de presse au XIXe siècle ?', 'mcq', '["Honoré Daumier","Gustave Doré","Édouard Manet","Félix Nadar"]'::jsonb, 0, 'Il publie notamment dans Le Charivari, sous la censure.', 8),
    ('5d93b840-6dca-533d-9a26-6eb2adf9bdbf'::uuid, '649b1a51-71b2-56c5-9dd0-28637957eda6'::uuid, 'Quel événement provoque l’exil de Victor Hugo ?', 'mcq', '["Le coup d’État du 2 décembre 1851","La révolution de 1848","La Commune de Paris","La guerre de 1870"]'::jsonb, 0, 'Il s’oppose à Louis-Napoléon Bonaparte, futur Napoléon III.', 1),
    ('3b59a70d-3c4a-58db-b407-db4ed2035c4b'::uuid, '649b1a51-71b2-56c5-9dd0-28637957eda6'::uuid, 'Sur quelle île Hugo passe-t-il l’essentiel de son exil ?', 'mcq', '["Guernesey","La Corse","Sainte-Hélène","Malte"]'::jsonb, 0, 'Après Bruxelles et Jersey.', 2),
    ('cc5f7101-ffd1-5a59-8ad8-72d0598e16e3'::uuid, '649b1a51-71b2-56c5-9dd0-28637957eda6'::uuid, 'Pourquoi refuse-t-il l’amnistie de 1859 ?', 'mcq', '["Il ne veut rentrer que lorsque la liberté sera rétablie","Il craint d’être arrêté","Il ne peut plus voyager","Il a perdu la nationalité française"]'::jsonb, 0, 'Le refus transforme la punition en position morale.', 3),
    ('ef5e5d27-7e4e-56ba-9d86-2a7db46e6ac8'::uuid, '649b1a51-71b2-56c5-9dd0-28637957eda6'::uuid, 'Quel recueil de 1853 est le pamphlet en vers contre Napoléon III ?', 'mcq', '["Les Châtiments","Les Contemplations","Les Feuilles d’automne","La Légende des siècles"]'::jsonb, 0, 'Satire et invective y dominent.', 4),
    ('f2c83047-b549-5112-89f9-da0f18380c17'::uuid, '649b1a51-71b2-56c5-9dd0-28637957eda6'::uuid, 'Quel deuil est au cœur des Contemplations ?', 'mcq', '["La mort de sa fille Léopoldine","La mort de sa femme","La mort de son frère","La mort de son père"]'::jsonb, 0, 'Noyée en 1843 ; le recueil se partage entre « Autrefois » et « Aujourd’hui ».', 5),
    ('9aebbf46-ac16-5d4d-833d-da973c396ec3'::uuid, '649b1a51-71b2-56c5-9dd0-28637957eda6'::uuid, 'Quelle figure oppose deux réalités, ici le pays perdu et l’île ?', 'mcq', '["L’antithèse","L’allitération","L’ellipse","La litote"]'::jsonb, 0, 'Elle structure toute la poésie de l’exil.', 6),
    ('a346aceb-c3cd-5eec-948f-e35fa872b2a2'::uuid, '649b1a51-71b2-56c5-9dd0-28637957eda6'::uuid, 'Hugo a cessé d’écrire pendant son exil.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il y écrit notamment Les Misérables.', 7),
    ('cc0fd7cd-0f52-596d-a421-26ac214d8190'::uuid, '649b1a51-71b2-56c5-9dd0-28637957eda6'::uuid, 'Quel vers résume la solitude assumée du poète en exil ?', 'mcq', '["« Et s’il n’en reste qu’un, je serai celui-là »","« Demain, dès l’aube… »","« Je suis une force qui va »","« Un vent d’oubli passe sur nous »"]'::jsonb, 0, 'Il clôt Ultima verba, dans Les Châtiments.', 8),
    ('4a0d7caf-8953-5a06-84b7-71aec750c896'::uuid, '06471920-b527-5c03-81c4-af180390c6bb'::uuid, 'Quelle différence entre exil subi et exil intérieur ?', 'mcq', '["L’un fait quitter le pays, l’autre se vit sur place sans s’y reconnaître","L’un est temporaire, l’autre définitif","L’un concerne les écrivains, l’autre les citoyens","Il n’y a aucune différence"]'::jsonb, 0, 'Beaucoup de poèmes du XXe siècle mêlent les deux.', 1),
    ('4f130e9a-e3f3-5d98-ae2b-671a8bcca942'::uuid, '06471920-b527-5c03-81c4-af180390c6bb'::uuid, 'Quel poète forge le mot négritude dans le Cahier d’un retour au pays natal ?', 'mcq', '["Aimé Césaire","Léopold Sédar Senghor","Mahmoud Darwich","Paul Celan"]'::jsonb, 0, 'Le mot retourne une insulte en fierté.', 2),
    ('59b14539-440d-5e2d-a3e0-17129a158428'::uuid, '06471920-b527-5c03-81c4-af180390c6bb'::uuid, 'Dans quelle langue Paul Celan, rescapé de la Shoah, écrit-il ?', 'mcq', '["En allemand","En yiddish","En roumain","En français"]'::jsonb, 0, 'Écrire dans la langue des bourreaux est au cœur de son œuvre.', 3),
    ('06f41d1d-df55-5a5e-b7cb-90a3e170d232'::uuid, '06471920-b527-5c03-81c4-af180390c6bb'::uuid, 'Quel poète fait de la Palestine perdue un territoire de langue ?', 'mcq', '["Mahmoud Darwich","Nâzim Hikmet","Aimé Césaire","Léopold Sédar Senghor"]'::jsonb, 0, 'La langue devient le pays qui manque.', 4),
    ('9dd561fe-5568-5f2b-9dd8-6f70854caaa1'::uuid, '06471920-b527-5c03-81c4-af180390c6bb'::uuid, 'Quelle forme le poème d’exil privilégie-t-il souvent au XXe siècle ?', 'mcq', '["Le vers libre, avec ruptures et blancs","L’alexandrin régulier","Le sonnet","La ballade"]'::jsonb, 0, 'La forme imite la rupture qu’elle raconte.', 5),
    ('ad67e9a1-42ff-5097-afaf-40fe1231a30f'::uuid, '06471920-b527-5c03-81c4-af180390c6bb'::uuid, 'Qu’appelle-t-on plurilinguisme dans un poème ?', 'mcq', '["La présence de plusieurs langues dans le même texte","La traduction du poème","L’emploi de mots rares","Le mélange de prose et de vers"]'::jsonb, 0, 'Des mots de la langue perdue surgissent dans le poème.', 6),
    ('d83266c6-f55c-541f-a46a-d6e35495ae44'::uuid, '06471920-b527-5c03-81c4-af180390c6bb'::uuid, 'La chanson a prolongé les poèmes d’exil au XXe siècle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle circule là où le livre n’entre pas.', 7),
    ('239980a4-b861-597e-bac6-42cbd6f8caec'::uuid, '06471920-b527-5c03-81c4-af180390c6bb'::uuid, 'Que faut-il chercher en lisant un poème d’exil ?', 'mcq', '["Ce qu’il nomme, ce qu’il tait, et ce que sa forme imite","Le nombre de strophes uniquement","La date de publication seule","La biographie complète de l’auteur"]'::jsonb, 0, 'Le non-dit est aussi signifiant que le dit.', 8),
    ('71f12824-7136-54e1-b197-23e4b86eaaa4'::uuid, '53a5c91b-12ff-5587-b4c7-3938e8147d50'::uuid, 'D’où vient Sonia Ristić ?', 'mcq', '["De Belgrade, en ex-Yougoslavie","De Grèce","Du Maroc","De Roumanie"]'::jsonb, 0, 'Elle a elle-même connu l’exil pendant les guerres de Yougoslavie.', 1),
    ('9391bc40-c574-5e6f-987b-7f972937af57'::uuid, '53a5c91b-12ff-5587-b4c7-3938e8147d50'::uuid, 'À quelle famille théâtrale la pièce Migrants appartient-elle ?', 'mcq', '["Le théâtre documentaire, ou théâtre du réel","La comédie de mœurs","La tragédie classique","Le vaudeville"]'::jsonb, 0, 'Elle part de témoignages et de documents.', 2),
    ('bbdc12e3-79ce-563b-9d7a-cd77bfef05a6'::uuid, '53a5c91b-12ff-5587-b4c7-3938e8147d50'::uuid, 'Qu’est-ce qu’une écriture chorale ?', 'mcq', '["Une écriture qui fait entendre plusieurs voix sans héros unique","Une pièce entièrement chantée","Un texte écrit à plusieurs auteurs","Un dialogue à deux personnages"]'::jsonb, 0, 'Elle remplace le destin individuel par une situation collective.', 3),
    ('c12f064e-5851-5c08-96fa-fd79c7d4f243'::uuid, '53a5c91b-12ff-5587-b4c7-3938e8147d50'::uuid, 'Quel effet vise le plateau vide, sans décor réaliste ?', 'mcq', '["Obliger le spectateur à imaginer","Réduire le coût de la production","Rendre la pièce plus courte","Faciliter les déplacements des acteurs"]'::jsonb, 0, 'L’imagination fait plus que l’illustration.', 4),
    ('2a6004df-93e7-5076-9a13-91f1fc33bbc1'::uuid, '53a5c91b-12ff-5587-b4c7-3938e8147d50'::uuid, 'Que signifie l’adresse directe au public au théâtre ?', 'mcq', '["Un personnage s’adresse aux spectateurs sans passer par la fiction","Les acteurs improvisent","Le public monte sur scène","Le texte est distribué à l’entrée"]'::jsonb, 0, 'Elle rompt l’illusion et implique la salle.', 5),
    ('433b288c-dbff-5f0f-a20d-0cd612d8522b'::uuid, '53a5c91b-12ff-5587-b4c7-3938e8147d50'::uuid, 'Quel est le pari du théâtre documentaire face aux chiffres de l’actualité ?', 'mcq', '["Le récit réveille là où le chiffre anesthésie","Le chiffre est plus convaincant","Il faut éviter tout témoignage","Il faut divertir avant d’informer"]'::jsonb, 0, 'Un nom et une durée d’attente frappent plus qu’une statistique.', 6),
    ('b8a94d16-87f3-585e-b490-6023fd83f49d'::uuid, '53a5c91b-12ff-5587-b4c7-3938e8147d50'::uuid, 'Migrants propose une solution politique claire en conclusion.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La pièce installe une question plutôt qu’une réponse.', 7),
    ('a95a1d70-eb4f-5932-8f4a-ea7e59ef13ae'::uuid, '53a5c91b-12ff-5587-b4c7-3938e8147d50'::uuid, 'Quelle question éthique traverse ce type d’œuvres ?', 'mcq', '["Comment représenter la souffrance d’autrui sans en faire un spectacle","Comment financer une création théâtrale","Comment écrire en alexandrins","Comment respecter les trois unités"]'::jsonb, 0, 'Elle vaut pour le théâtre, le roman et la photographie.', 8),
    ('ad261744-a0d1-5ef7-abca-90d7ea09317e'::uuid, '2b99bd69-f334-5be2-9b94-75643db89f08'::uuid, 'Le narrateur d’un roman est-il l’auteur ?', 'mcq', '["Non, c’est une voix construite par le texte","Oui, toujours","Oui, sauf dans les récits à la première personne","Seulement dans les romans historiques"]'::jsonb, 0, 'Confondre les deux est l’erreur la plus fréquente en commentaire.', 1),
    ('b60de5de-38c6-5bac-b219-16cc05da1dca'::uuid, '2b99bd69-f334-5be2-9b94-75643db89f08'::uuid, 'Qu’est-ce que la focalisation interne ?', 'mcq', '["On ne connaît que ce que sait un personnage","Le narrateur sait tout de tous","On ne voit que les comportements extérieurs","Le récit est écrit à la première personne"]'::jsonb, 0, 'Elle produit l’identification et le suspense par ignorance.', 2),
    ('701f9657-9262-5467-8708-8534cff2798c'::uuid, '2b99bd69-f334-5be2-9b94-75643db89f08'::uuid, 'Qu’est-ce qu’une ellipse narrative ?', 'mcq', '["Un moment du récit passé sous silence","Une longue description","Un dialogue rapporté","Un retour en arrière"]'::jsonb, 0, 'Elle accélère le récit en sautant du temps.', 3),
    ('676efe58-f4c9-5074-9b4a-6935faa15eec'::uuid, '2b99bd69-f334-5be2-9b94-75643db89f08'::uuid, 'Quel roman du XVIIIe siècle est écrit entièrement par lettres ?', 'mcq', '["Les Liaisons dangereuses","Manon Lescaut","Candide","La Princesse de Clèves"]'::jsonb, 0, 'Laclos y fait de la forme épistolaire une arme.', 4),
    ('8ee4f486-b43b-5232-b3fe-069715d745d0'::uuid, '2b99bd69-f334-5be2-9b94-75643db89f08'::uuid, 'Que voulait faire Balzac avec La Comédie humaine ?', 'mcq', '["Faire concurrence à l’état civil en peignant toute la société","Écrire un seul roman parfait","Réformer la langue française","Défendre la monarchie"]'::jsonb, 0, 'Des personnages reparaissent d’un roman à l’autre.', 5),
    ('5fbc0af3-4f42-5886-8caf-64350085aae8'::uuid, '2b99bd69-f334-5be2-9b94-75643db89f08'::uuid, 'Quel écrivain revendique une méthode dite expérimentale pour le roman ?', 'mcq', '["Émile Zola","Gustave Flaubert","Stendhal","Marcel Proust"]'::jsonb, 0, 'Le naturalisme applique au récit un modèle scientifique.', 6),
    ('d04c8a55-75b0-51f3-acc3-376e3bf240d6'::uuid, '2b99bd69-f334-5be2-9b94-75643db89f08'::uuid, 'Le XXe siècle conserve intacte la structure du roman réaliste.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Monologue intérieur, chronologie éclatée, personnage instable la défont.', 7),
    ('b88346b8-92bf-5123-afdb-8866af90506a'::uuid, '2b99bd69-f334-5be2-9b94-75643db89f08'::uuid, 'Qu’est-ce que l’autofiction ?', 'mcq', '["Un récit qui mêle éléments autobiographiques et fiction assumée","Une biographie officielle","Un roman écrit par plusieurs auteurs","Un récit de voyage"]'::jsonb, 0, 'Le pacte de lecture y est volontairement ambigu.', 8),
    ('233a7c8d-3b36-57af-8eea-740927a6b6b0'::uuid, 'c43fe0db-1a8d-5a40-8587-cba913e6441d'::uuid, 'Qu’est-ce que le discours indirect libre ?', 'mcq', '["Les pensées d’un personnage passent dans le récit sans guillemets ni verbe introducteur","Un dialogue entre deux personnages","Un monologue au théâtre","Une citation entre guillemets"]'::jsonb, 0, 'Il permet l’ironie : on ne sait plus qui parle, du personnage ou du narrateur.', 1),
    ('b30c3f94-3156-5b1a-a160-d76114feae44'::uuid, 'c43fe0db-1a8d-5a40-8587-cba913e6441d'::uuid, 'De qui Maupassant a-t-il été l’élève ?', 'mcq', '["Gustave Flaubert","Honoré de Balzac","Victor Hugo","Stendhal"]'::jsonb, 0, 'Flaubert lui apprend l’exigence de la phrase.', 2),
    ('63ac9797-3de5-521e-998b-0fef0aa491aa'::uuid, 'c43fe0db-1a8d-5a40-8587-cba913e6441d'::uuid, 'Qu’est-ce que la chute d’une nouvelle ?', 'mcq', '["Le retournement final qui éclaire tout le récit","La première phrase","La description initiale","Le titre du texte"]'::jsonb, 0, 'Dans « La Parure », elle révèle que le bijou était faux.', 3),
    ('347d2c04-0c96-51c6-82e5-65649637d0ae'::uuid, 'c43fe0db-1a8d-5a40-8587-cba913e6441d'::uuid, 'Que dénonce « Boule de suif » ?', 'mcq', '["L’hypocrisie et la lâcheté des notables","La misère paysanne","La corruption de la presse","L’exil politique"]'::jsonb, 0, 'Ils se servent d’une prostituée puis la méprisent.', 4),
    ('73d0f2c1-8112-5c5f-bf9d-dcb1dff47560'::uuid, 'c43fe0db-1a8d-5a40-8587-cba913e6441d'::uuid, 'Quel objet ordinaire suffit souvent, chez Maupassant, à dire une position sociale ?', 'mcq', '["Un détail matériel comme une robe ou une pièce de monnaie","Un discours du narrateur","Une citation latine","Un portrait psychologique long"]'::jsonb, 0, 'Montrer plutôt qu’expliquer : c’est la méthode réaliste.', 5),
    ('fcd9d5f5-a5e0-52ca-ab74-e328a2fbb45b'::uuid, 'c43fe0db-1a8d-5a40-8587-cba913e6441d'::uuid, 'Qu’ajoute le naturalisme au programme réaliste ?', 'mcq', '["L’idée que le personnage est le produit de son hérédité et de son milieu","Le refus de la description","Le retour au merveilleux","L’abandon du narrateur externe"]'::jsonb, 0, 'Zola en fait une méthode revendiquée.', 6),
    ('ae161caa-106a-5198-bc32-871e0c4481d9'::uuid, 'c43fe0db-1a8d-5a40-8587-cba913e6441d'::uuid, 'Le réalisme décrit le monde sans jamais porter de jugement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le choix de ce qu’on décrit est déjà un jugement.', 7),
    ('cc14833c-20a5-5901-9dd7-91f3d5a2b0ae'::uuid, 'c43fe0db-1a8d-5a40-8587-cba913e6441d'::uuid, 'Quel ton domine chez Maupassant pour laisser les personnages se juger eux-mêmes ?', 'mcq', '["Une ironie froide","Le lyrisme","L’emphase épique","Le pathétique appuyé"]'::jsonb, 0, 'Le narrateur ne commente pas : il rapporte.', 8),
    ('67421fc3-f2c9-5f77-b0d2-2e7f6c0049ab'::uuid, 'a821924b-0239-5c23-842e-27f53b083f1b'::uuid, 'En quelle année paraît L’Étranger ?', 'mcq', '["1942","1932","1957","1968"]'::jsonb, 0, 'Camus recevra le prix Nobel en 1957.', 1),
    ('1aecc390-bcc4-5e86-8daf-02254c9dd436'::uuid, 'a821924b-0239-5c23-842e-27f53b083f1b'::uuid, 'Comment s’appelle le narrateur du roman ?', 'mcq', '["Meursault","Rieux","Caligula","Clamence"]'::jsonb, 0, 'Il raconte à la première personne.', 2),
    ('53aaea7a-7e93-5b84-b23b-c96fb59dc79a'::uuid, 'a821924b-0239-5c23-842e-27f53b083f1b'::uuid, 'Quel temps verbal domine le récit ?', 'mcq', '["Le passé composé","Le passé simple","Le présent de narration","L’imparfait"]'::jsonb, 0, 'Il donne au récit sa platitude volontaire.', 3),
    ('97e54770-99ec-563f-96f5-a0085dfa3437'::uuid, 'a821924b-0239-5c23-842e-27f53b083f1b'::uuid, 'Qu’appelle-t-on la voix blanche du roman ?', 'mcq', '["Une écriture neutre, sans effets ni explications","Un narrateur qui crie","Un texte sans dialogue","Un récit écrit en vers"]'::jsonb, 0, 'Elle produit le malaise du lecteur.', 4),
    ('15e91aa7-8598-5771-b915-24ad8f3801a5'::uuid, 'a821924b-0239-5c23-842e-27f53b083f1b'::uuid, 'Pour quoi Meursault est-il en réalité condamné, selon le roman ?', 'mcq', '["Pour son écart avec les rituels sociaux, autant que pour le meurtre","Pour vol","Pour trahison","Pour blasphème"]'::jsonb, 0, 'On lui reproche de n’avoir pas pleuré à l’enterrement de sa mère.', 5),
    ('3b33ad6c-0c83-563d-9a4e-01b3243b2664'::uuid, 'a821924b-0239-5c23-842e-27f53b083f1b'::uuid, 'Dans quel cycle Camus range-t-il L’Étranger ?', 'mcq', '["Le cycle de l’absurde","Le cycle de la révolte","Le cycle de l’amour","Le cycle du pouvoir"]'::jsonb, 0, 'Avec Le Mythe de Sisyphe et Caligula.', 6),
    ('2f6ca226-fd63-51fc-9a9c-0de728e5d3a8'::uuid, 'a821924b-0239-5c23-842e-27f53b083f1b'::uuid, 'Qu’est-ce que l’absurde chez Camus ?', 'mcq', '["La rencontre entre le besoin humain de sens et le silence du monde","Une situation comique","Une erreur de raisonnement","Un refus de la morale"]'::jsonb, 0, 'La lucidité, et non le désespoir, en est la réponse.', 7),
    ('71de21b1-c34c-5628-bf31-dda70271a25d'::uuid, 'a821924b-0239-5c23-842e-27f53b083f1b'::uuid, 'La seconde partie du roman raconte des faits nouveaux, sans lien avec la première.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle relit les mêmes faits et montre comment on fabrique une culpabilité.', 8),
    ('6a603fae-9f62-5432-a7f0-d698d0fefa49'::uuid, 'e5896972-e15f-5e55-929f-01602463db50'::uuid, 'Qu’est-ce que le pacte autobiographique ?', 'mcq', '["L’identité entre auteur, narrateur et personnage","La promesse de ne rien inventer","Le contrat avec l’éditeur","L’engagement à publier après sa mort"]'::jsonb, 0, 'La formule est de Philippe Lejeune.', 1),
    ('50792eaa-6776-57dd-93cd-6e4cca60b562'::uuid, 'e5896972-e15f-5e55-929f-01602463db50'::uuid, 'Qu’est-ce qui distingue le journal intime de l’autobiographie ?', 'mcq', '["Il s’écrit au jour le jour, sans recul rétrospectif","Il est toujours publié","Il est écrit à la troisième personne","Il concerne uniquement l’enfance"]'::jsonb, 0, 'L’autobiographie est un récit rétrospectif.', 2),
    ('5dd7d029-043c-5da8-873f-c0d9fb0697b9'::uuid, 'e5896972-e15f-5e55-929f-01602463db50'::uuid, 'Qui ouvre Les Confessions en 1782 en promettant de tout dire ?', 'mcq', '["Jean-Jacques Rousseau","Michel de Montaigne","Chateaubriand","Voltaire"]'::jsonb, 0, 'Un texte fondateur du genre.', 3),
    ('d2e88e97-d4fe-5a1c-86a3-ee21bee9aa06'::uuid, 'e5896972-e15f-5e55-929f-01602463db50'::uuid, 'Quel écrivain italien témoigne de la déportation dans un récit devenu classique ?', 'mcq', '["Primo Levi","Italo Calvino","Umberto Eco","Alberto Moravia"]'::jsonb, 0, 'Témoigner est l’une des grandes raisons de s’écrire.', 4),
    ('c263f91d-1318-5eda-b93e-e60876ee05d6'::uuid, 'e5896972-e15f-5e55-929f-01602463db50'::uuid, 'Quelle particularité de style caractérise Annie Ernaux ?', 'mcq', '["Une écriture plate, sans effets, assumée comme un choix","Un lyrisme abondant","Un vocabulaire savant","Un récit en vers"]'::jsonb, 0, 'Ne pas trahir par le style le milieu dont elle vient.', 5),
    ('a49b7c24-878a-5df0-993e-3f11dd7a706a'::uuid, 'e5896972-e15f-5e55-929f-01602463db50'::uuid, 'Quels deux « je » cohabitent dans un texte autobiographique ?', 'mcq', '["Celui qui a vécu et celui qui écrit","Le vrai et le faux","L’auteur et l’éditeur","Le narrateur et le lecteur"]'::jsonb, 0, 'Le second sait ce que le premier ignorait.', 6),
    ('f40525fb-05cf-5a20-9e5a-6981227e923b'::uuid, 'e5896972-e15f-5e55-929f-01602463db50'::uuid, 'La sincérité d’un auteur garantit la vérité de son récit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La mémoire trie et déforme, et l’on se raconte toujours pour quelqu’un.', 7),
    ('cbcc4fe0-84a7-5520-baf3-86160b5907c7'::uuid, 'e5896972-e15f-5e55-929f-01602463db50'::uuid, 'Qu’est-ce qu’un récit de filiation ?', 'mcq', '["Un récit qui part des parents ou grands-parents pour se comprendre soi","Une biographie d’un inconnu","Un arbre généalogique commenté","Un roman historique familial"]'::jsonb, 0, 'Une forme très présente dans la littérature contemporaine.', 8),
    ('07b79c34-bcfb-52ba-87ca-7655b7ccf11d'::uuid, '65db08d9-dd67-5896-82e9-310c368ae803'::uuid, 'En quelle année paraît Qu’Allah bénisse la France ?', 'mcq', '["2004","1994","2014","2020"]'::jsonb, 0, 'Le film que l’auteur en tire date, lui, de 2014.', 1),
    ('2280026d-7fcf-53f6-a6d5-aff0fd23ec0d'::uuid, '65db08d9-dd67-5896-82e9-310c368ae803'::uuid, 'Dans quel quartier de Strasbourg l’auteur a-t-il grandi ?', 'mcq', '["Le Neuhof","La Meinau","La Krutenau","Hautepierre"]'::jsonb, 0, 'Le quartier est un personnage du livre.', 2),
    ('6bab267e-9f9b-5b73-9399-9a9afb006a17'::uuid, '65db08d9-dd67-5896-82e9-310c368ae803'::uuid, 'Quelle est la profession première d’Abd Al Malik ?', 'mcq', '["Rappeur","Journaliste","Professeur","Comédien"]'::jsonb, 0, 'Il vient du groupe NAP avant sa carrière solo.', 3),
    ('cc1822d9-c34e-53c9-8b41-17a6373c006b'::uuid, '65db08d9-dd67-5896-82e9-310c368ae803'::uuid, 'Qu’est-ce qu’un récit de transfuge social ?', 'mcq', '["Le récit de quelqu’un qui change de monde social et en garde la trace","Le récit d’un exil politique","Le récit d’un voyage à l’étranger","Le récit d’une conversion religieuse uniquement"]'::jsonb, 0, 'La réussite n’efface jamais le point de départ.', 4),
    ('15c10b48-18a7-586f-9082-5dd8700a5ec5'::uuid, '65db08d9-dd67-5896-82e9-310c368ae803'::uuid, 'Pourquoi le titre est-il une provocation calculée ?', 'mcq', '["Il accole deux mots que le débat public croit incompatibles","Il cite un slogan politique","Il traduit une prière ancienne","Il reprend un titre de chanson américaine"]'::jsonb, 0, 'Le livre travaille à montrer qu’ils ne le sont pas.', 5),
    ('0df0e193-c5a1-5f17-8fbb-84cb21745124'::uuid, '65db08d9-dd67-5896-82e9-310c368ae803'::uuid, 'Quelle particularité présente la langue du récit ?', 'mcq', '["Elle mêle français courant, argot, verlan et références religieuses","Elle est écrite en vers libres","Elle n’emploie que le passé simple","Elle est entièrement en langue lingala"]'::jsonb, 0, 'La langue composite est le sujet même du livre.', 6),
    ('88f899cd-99b4-52b4-8fe0-784534017655'::uuid, '65db08d9-dd67-5896-82e9-310c368ae803'::uuid, 'Le récit idéalise la vie dans les quartiers populaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il refuse autant l’idéalisation que le décor de misère.', 7),
    ('f47ee81d-5a37-5c09-ae44-45f793557974'::uuid, '65db08d9-dd67-5896-82e9-310c368ae803'::uuid, 'Quelle valeur le livre défend-il comme moyen de s’en sortir ?', 'mcq', '["L’éducation et le travail sur soi","La force physique","La chance","Le silence"]'::jsonb, 0, 'Avec la parole, qui permet d’exister publiquement.', 8),
    ('14ba6ca2-3442-5ec7-a36d-6c0f1f4a881d'::uuid, 'b8d318f5-935d-5252-8726-df48fb8de8a5'::uuid, 'Quel rôle joue la ville dans un récit réaliste ?', 'mcq', '["Elle classe socialement les personnages","Elle sert uniquement de décor","Elle remplace l’intrigue","Elle n’a pas d’importance"]'::jsonb, 0, 'Dire où l’on habite, c’est dire ce qu’on peut espérer.', 1),
    ('7ec6d988-a623-5ebd-ad1b-f7113eb3945c'::uuid, 'b8d318f5-935d-5252-8726-df48fb8de8a5'::uuid, 'Quelle pension parisienne ouvre Le Père Goriot de Balzac ?', 'mcq', '["La pension Vauquer","La pension Vauquelin","La pension Sainte-Périne","La pension Grandet"]'::jsonb, 0, 'Sa description est une analyse sociale déguisée.', 2),
    ('65eace09-aa6b-5393-a7af-70afb5a00f34'::uuid, 'b8d318f5-935d-5252-8726-df48fb8de8a5'::uuid, 'Quel roman de Zola se déroule dans un grand magasin ?', 'mcq', '["Au Bonheur des Dames","Germinal","L’Assommoir","La Bête humaine"]'::jsonb, 0, 'Le commerce moderne y est décrit comme une machine.', 3),
    ('f2214c00-ee37-5994-868e-7aff46131b7f'::uuid, 'b8d318f5-935d-5252-8726-df48fb8de8a5'::uuid, 'Quelle figure désigne un ensemble par l’un de ses éléments, comme « la cité » pour ses habitants ?', 'mcq', '["La métonymie","La comparaison","L’hyperbole","La litote"]'::jsonb, 0, 'Elle peut aussi effacer les individus derrière le lieu.', 4),
    ('619c1be2-0287-5f0b-a0b3-4b3598d46bdb'::uuid, 'b8d318f5-935d-5252-8726-df48fb8de8a5'::uuid, 'Pourquoi la question « qui parle ? » est-elle décisive dans les écritures urbaines ?', 'mcq', '["Parce que le point de vue produit sympathie, peur ou indifférence","Parce que l’auteur doit être connu","Parce que le narrateur doit être omniscient","Parce que le récit doit être vrai"]'::jsonb, 0, 'Voir la cité de l’intérieur ou depuis une voiture qui passe ne donne pas le même texte.', 5),
    ('a3845a37-a284-594e-ba82-28d35ce0751d'::uuid, 'b8d318f5-935d-5252-8726-df48fb8de8a5'::uuid, 'Quelles formes venues d’ailleurs nourrissent la littérature urbaine contemporaine ?', 'mcq', '["Le rap, le slam, les séries et le documentaire","Le sonnet et l’ode","La tragédie classique","Le conte merveilleux"]'::jsonb, 0, 'Elles imposent leurs images de la ville.', 6),
    ('829e37f2-b2cc-5c2a-bc6b-7a82cb37bc8b'::uuid, 'b8d318f5-935d-5252-8726-df48fb8de8a5'::uuid, 'Une description de ville est un élément neutre du récit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle porte toujours un jugement social implicite.', 7),
    ('76fa8084-d8d8-5fbd-ad6b-4a30066bd0d3'::uuid, 'b8d318f5-935d-5252-8726-df48fb8de8a5'::uuid, 'Quel effet produit l’emploi du discours direct et de l’argot dans ces récits ?', 'mcq', '["Faire entendre une langue réelle et rendre la parole aux personnages","Rendre le texte plus difficile","Allonger le récit","Respecter les règles classiques"]'::jsonb, 0, 'L’oralité est un choix politique autant que stylistique.', 8),
    ('8b32dc3b-c9c5-55d9-95da-5a9b2f2334c8'::uuid, '9d0b18fb-cdab-51f2-a5b3-744420699fea'::uuid, 'Qu’est-ce qu’une didascalie ?', 'mcq', '["Une indication scénique non prononcée par les acteurs","Une longue réplique","Un monologue","Une scène muette"]'::jsonb, 0, 'Elle précise décor, gestes, ton, entrées et sorties.', 1),
    ('10b9b9fa-9ca6-500e-be35-c83de39f7e89'::uuid, '9d0b18fb-cdab-51f2-a5b3-744420699fea'::uuid, 'Qu’est-ce qu’un aparté ?', 'mcq', '["Une parole adressée au public sans être entendue des autres personnages","Un dialogue rapide","Une réplique de plus de dix vers","Une scène sans dialogue"]'::jsonb, 0, 'Il joue de la complicité avec la salle.', 2),
    ('66ee4877-ce97-5283-8c0c-060f27ec213e'::uuid, '9d0b18fb-cdab-51f2-a5b3-744420699fea'::uuid, 'Qu’est-ce que la double énonciation ?', 'mcq', '["Un personnage parle à un autre, et l’auteur parle en même temps au public","Deux acteurs disent la même réplique","Un texte joué deux fois","Un dialogue traduit en deux langues"]'::jsonb, 0, 'C’est la clé de lecture du genre théâtral.', 3),
    ('e8ba4486-5e4b-5851-be77-052e2a58f48f'::uuid, '9d0b18fb-cdab-51f2-a5b3-744420699fea'::uuid, 'Quand change-t-on de scène dans une pièce classique ?', 'mcq', '["Quand un personnage entre ou sort","À chaque changement de décor","Toutes les dix répliques","À chaque acte"]'::jsonb, 0, 'C’est une convention d’écriture, pas de mise en scène.', 4),
    ('ddc675bc-99d5-5eb3-b7da-fc76dde82f4f'::uuid, '9d0b18fb-cdab-51f2-a5b3-744420699fea'::uuid, 'Quelles sont les trois unités de la tragédie classique ?', 'mcq', '["Un jour, un lieu, une action","Un acte, une scène, un personnage","Le temps, l’espace, la parole","La vraisemblance, la bienséance, la clarté"]'::jsonb, 0, 'La vraisemblance et la bienséance sont d’autres règles.', 5),
    ('edf9980c-0308-56a8-802e-f482d4fdaf76'::uuid, '9d0b18fb-cdab-51f2-a5b3-744420699fea'::uuid, 'Qu’interdit la règle de bienséance au XVIIe siècle ?', 'mcq', '["Montrer la mort et la violence sur scène","Faire rire le public","Employer le vers","Changer de décor"]'::jsonb, 0, 'La violence est racontée par un récit, non montrée.', 6),
    ('87f4b1f4-4286-591e-979a-9bfbd58f8c5f'::uuid, '9d0b18fb-cdab-51f2-a5b3-744420699fea'::uuid, 'Qu’est-ce que l’ironie tragique ?', 'mcq', '["Un personnage dit plus qu’il ne croit dire, et le spectateur le sait","Une plaisanterie dans une tragédie","Un dénouement heureux","Une réplique adressée au public"]'::jsonb, 0, 'Elle repose sur l’écart entre son savoir et celui du personnage.', 7),
    ('ef165e10-f62c-5a7c-bd71-dd29aac5a5f2'::uuid, '9d0b18fb-cdab-51f2-a5b3-744420699fea'::uuid, 'Deux mises en scène d’un même texte disent nécessairement la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La mise en scène est une interprétation : c’est ce qui fait vivre les pièces.', 8),
    ('4f5918bc-d39f-51c5-b3bd-384bc5f56d38'::uuid, '34956f40-fa6b-598e-b3ad-da2598d1d1f6'::uuid, 'Comment s’appellent les deux familles ennemies de la pièce ?', 'mcq', '["Les Montaigu et les Capulet","Les Médicis et les Borgia","Les York et les Lancastre","Les Sforza et les Visconti"]'::jsonb, 0, 'Leur haine n’a plus d’origine connue.', 1),
    ('78eab167-95df-519a-a4eb-e0312cb715af'::uuid, '34956f40-fa6b-598e-b3ad-da2598d1d1f6'::uuid, 'Que révèle le prologue de la pièce ?', 'mcq', '["Que les deux amants vont mourir","Le nom du meurtrier","La fin heureuse de l’histoire","Le lieu de la dernière scène uniquement"]'::jsonb, 0, 'Le spectateur regarde alors comment la fin devient inévitable.', 2),
    ('085c4f3d-589e-5731-886f-9f10a4ea63de'::uuid, '34956f40-fa6b-598e-b3ad-da2598d1d1f6'::uuid, 'Dans quelle ville se déroule l’action ?', 'mcq', '["Vérone","Venise","Florence","Milan"]'::jsonb, 0, 'Shakespeare situe plusieurs pièces en Italie.', 3),
    ('642c3058-5b21-50ab-9e57-6825ae216b23'::uuid, '34956f40-fa6b-598e-b3ad-da2598d1d1f6'::uuid, 'Quel élément, très concret, précipite le dénouement ?', 'mcq', '["Un message qui n’arrive pas à temps","Une trahison de la nourrice","Un duel perdu par Juliette","Une décision du prince"]'::jsonb, 0, 'La fatalité passe par des détails ordinaires.', 4),
    ('5f14d849-43c0-5c22-b8cf-ec269c818889'::uuid, '34956f40-fa6b-598e-b3ad-da2598d1d1f6'::uuid, 'En quoi Shakespeare s’éloigne-t-il des futures règles classiques françaises ?', 'mcq', '["Il mêle comique et tragique, change de lieu et étend la durée","Il refuse les dialogues","Il n’écrit qu’en prose","Il supprime les personnages secondaires"]'::jsonb, 0, 'Cette liberté deviendra le modèle des romantiques.', 5),
    ('7af5ff41-9da9-5c31-b5b5-01feba0b0802'::uuid, '34956f40-fa6b-598e-b3ad-da2598d1d1f6'::uuid, 'Quelle forme poétique les amants partagent-ils lors de leur première rencontre ?', 'mcq', '["Un sonnet","Une ballade","Une ode","Un rondeau"]'::jsonb, 0, 'Leur langue commune scelle leur accord avant les mots d’amour.', 6),
    ('171f8289-fe84-5826-b35e-216f3f213db6'::uuid, '34956f40-fa6b-598e-b3ad-da2598d1d1f6'::uuid, 'Quelle comédie musicale transpose l’intrigue dans les gangs de New York ?', 'mcq', '["West Side Story","Cabaret","Chicago","Hair"]'::jsonb, 0, 'La pièce fonctionne partout où il y a deux camps et une frontière.', 7),
    ('6ad89108-e2f6-5da0-bde7-88f024c14fe6'::uuid, '34956f40-fa6b-598e-b3ad-da2598d1d1f6'::uuid, 'Dans la pièce, l’amour de Roméo et Juliette est un choix sans conséquence politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Choisir l’autre camp, c’est trahir le sien.', 8),
    ('e6f8e01f-48cb-51eb-9372-f32ca01213cc'::uuid, '0cbab3bc-e866-595c-b182-14fa704a9acf'::uuid, 'En quelle année Musset publie-t-il Les Caprices de Marianne ?', 'mcq', '["1833","1830","1843","1827"]'::jsonb, 0, 'Dans le recueil Un spectacle dans un fauteuil.', 1),
    ('c3065f75-bb11-51e9-bb80-ad17f21a7605'::uuid, '0cbab3bc-e866-595c-b182-14fa704a9acf'::uuid, 'Qui aime Marianne au début de la pièce ?', 'mcq', '["Cœlio","Octave","Claudio","Tibia"]'::jsonb, 0, 'Il charge son ami Octave de plaider sa cause.', 2),
    ('aa46c590-f38b-5126-a392-a59d803a75ea'::uuid, '0cbab3bc-e866-595c-b182-14fa704a9acf'::uuid, 'Qui est Claudio ?', 'mcq', '["Le vieux juge, mari de Marianne","Le père de Cœlio","Un ami d’Octave","Un serviteur"]'::jsonb, 0, 'C’est lui qui fait tendre le piège mortel.', 3),
    ('e90b95a7-58d3-5dfb-9bad-3039d43ec3c6'::uuid, '0cbab3bc-e866-595c-b182-14fa704a9acf'::uuid, 'Comment Musset caractérise-t-il Cœlio et Octave ?', 'mcq', '["Comme deux moitiés d’un même homme","Comme deux frères ennemis","Comme maître et valet","Comme rivaux politiques"]'::jsonb, 0, 'L’idéaliste et le libertin s’éclairent l’un l’autre.', 4),
    ('91817534-8aba-5830-8f40-6eb97a52b014'::uuid, '0cbab3bc-e866-595c-b182-14fa704a9acf'::uuid, 'À quoi correspondent en réalité les « caprices » de Marianne ?', 'mcq', '["Aux seules libertés que sa condition lui laisse","À une maladie nerveuse","À un jeu cruel gratuit","À une stratégie financière"]'::jsonb, 0, 'La pièce interroge la condition des femmes mariées.', 5),
    ('15afd86f-a70d-546b-ad1b-810283ba97d4'::uuid, '0cbab3bc-e866-595c-b182-14fa704a9acf'::uuid, 'Quel texte sert de manifeste au drame romantique ?', 'mcq', '["La préface de Cromwell, de Victor Hugo","L’Art poétique de Boileau","La préface de Pierre et Jean","Le Discours de la méthode"]'::jsonb, 0, 'Publiée en 1827, trois ans avant la bataille d’Hernani.', 6),
    ('258284af-d6b9-5350-a6e7-89a570f194b2'::uuid, '0cbab3bc-e866-595c-b182-14fa704a9acf'::uuid, 'Qu’appelle-t-on le mal du siècle chez les romantiques ?', 'mcq', '["Le désœuvrement d’une génération née après l’épopée napoléonienne","Une épidémie du XIXe siècle","La misère ouvrière","La censure du théâtre"]'::jsonb, 0, 'Musset l’analyse dans La Confession d’un enfant du siècle.', 7),
    ('cf832456-3255-5fdc-815c-44301eb3e713'::uuid, '0cbab3bc-e866-595c-b182-14fa704a9acf'::uuid, 'Le drame romantique respecte la règle des trois unités.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il la refuse, comme il refuse la séparation des registres.', 8),
    ('effbcfae-7eea-5795-ac00-bd548e32cb6a'::uuid, '1d4a0092-0f72-51dc-bcb0-0a7bae065e74'::uuid, 'Qui a écrit Roberto Zucco ?', 'mcq', '["Bernard-Marie Koltès","Jean Genet","Samuel Beckett","Eugène Ionesco"]'::jsonb, 0, 'La pièce est créée en 1990, après la mort de l’auteur.', 1),
    ('74baa53f-476c-5f02-9b4c-91bc1bfc2da4'::uuid, '1d4a0092-0f72-51dc-bcb0-0a7bae065e74'::uuid, 'De quoi la pièce s’inspire-t-elle ?', 'mcq', '["D’un fait divers, le parcours du criminel Roberto Succo","D’un mythe grec","D’un roman de Camus","D’un épisode de la Résistance"]'::jsonb, 0, 'Koltès en fait une figure, non un portrait.', 2),
    ('2ff8f4d1-0b23-5bf1-88f6-84d5c82442e1'::uuid, '1d4a0092-0f72-51dc-bcb0-0a7bae065e74'::uuid, 'Comment la pièce est-elle découpée ?', 'mcq', '["En quinze tableaux titrés","En cinq actes","En trois journées","En scènes numérotées sans titre"]'::jsonb, 0, 'Une progression par stations, de lieu en lieu.', 3),
    ('7380d38f-98ba-5e7c-a206-86cf7f592e02'::uuid, '1d4a0092-0f72-51dc-bcb0-0a7bae065e74'::uuid, 'Comment les autres personnages sont-ils désignés ?', 'mcq', '["Par leur fonction : la Gamine, la Mère, la Dame","Par leur prénom complet","Par des numéros","Par leur métier uniquement"]'::jsonb, 0, 'Cela les rapproche des figures mythiques.', 4),
    ('15229226-f8a5-5100-bc1b-fda2974dd32b'::uuid, '1d4a0092-0f72-51dc-bcb0-0a7bae065e74'::uuid, 'Koltès explique-t-il les mobiles de son personnage ?', 'mcq', '["Non, il refuse toute explication psychologique","Oui, par une enfance maltraitée","Oui, par un mobile financier","Oui, par la vengeance"]'::jsonb, 0, 'Le personnage est une énergie qui passe et détruit.', 5),
    ('ef622176-d2df-5f58-8a71-9ae2d8b807e8'::uuid, '1d4a0092-0f72-51dc-bcb0-0a7bae065e74'::uuid, 'Où se déroule le dernier tableau de la pièce ?', 'mcq', '["Sur un toit, en plein soleil","Dans une prison","Dans un métro","Dans un parc"]'::jsonb, 0, 'La capture y devient une apothéose ambiguë.', 6),
    ('89599390-c3c1-5dcd-ba8e-c3c92c38f071'::uuid, '1d4a0092-0f72-51dc-bcb0-0a7bae065e74'::uuid, 'Quel débat la pièce a-t-elle provoqué ?', 'mcq', '["Représenter un criminel réel revient-il à le glorifier","Faut-il jouer en costume d’époque","Le théâtre doit-il être en vers","Peut-on jouer sans décor"]'::jsonb, 0, 'Koltès répond par le déplacement vers la figure mythique.', 7),
    ('a56f0bee-3e0e-56c8-b3ba-70e62c8082df'::uuid, '1d4a0092-0f72-51dc-bcb0-0a7bae065e74'::uuid, 'Dans la tragédie contemporaine, la fatalité vient encore des dieux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle prend la forme d’un déterminisme social et familial.', 8),
    ('7593d80f-f450-5600-9605-f590a42a0255'::uuid, 'ba7ea3af-f892-5617-ba6f-27a953f1cee0'::uuid, 'Comment la tragédie classique traite-t-elle la mort d’un personnage ?', 'mcq', '["Elle la fait raconter hors scène, par un récit","Elle la montre en détail","Elle la supprime de l’intrigue","Elle la met en musique"]'::jsonb, 0, 'C’est l’effet de la règle de bienséance.', 1),
    ('3b7b0e6d-d8bb-567d-b316-a8047df6904b'::uuid, 'ba7ea3af-f892-5617-ba6f-27a953f1cee0'::uuid, 'Qui, dans la tragédie grecque, vient raconter ce qui s’est passé hors scène ?', 'mcq', '["Le messager","Le coryphée","Le roi","Le devin"]'::jsonb, 0, 'La parole doit faire voir ce qu’on ne montre pas.', 2),
    ('c8c24074-9e8f-5a89-87b4-d50788771a33'::uuid, 'ba7ea3af-f892-5617-ba6f-27a953f1cee0'::uuid, 'Quel dramaturge français est célèbre pour ses récits de mort, comme celui d’Hippolyte ?', 'mcq', '["Jean Racine","Molière","Pierre Corneille","Beaumarchais"]'::jsonb, 0, 'Le récit de Théramène est un morceau de bravoure.', 3),
    ('faeb207a-d719-5954-aa4e-75f0bc6efb16'::uuid, 'ba7ea3af-f892-5617-ba6f-27a953f1cee0'::uuid, 'Quel théâtre, à l’inverse, laisse le plateau jonché de corps à la fin d’Hamlet ?', 'mcq', '["Le théâtre élisabéthain","Le théâtre classique français","Le théâtre de boulevard","La comédie italienne"]'::jsonb, 0, 'Shakespeare ne suit pas la règle de bienséance.', 4),
    ('0fef421d-c436-5c8f-b5ad-cdf85e64bf89'::uuid, 'ba7ea3af-f892-5617-ba6f-27a953f1cee0'::uuid, 'Que fait le théâtre de l’absurde de la mort ?', 'mcq', '["Il la transforme en durée et en attente","Il la rend comique","Il la supprime","Il la représente réalistement"]'::jsonb, 0, 'Chez Beckett, on n’en finit pas de mourir.', 5),
    ('b3477a69-0167-5152-9bac-8cc6bb42f772'::uuid, 'ba7ea3af-f892-5617-ba6f-27a953f1cee0'::uuid, 'Quelle pièce d’Ionesco fait de la mort une cérémonie lente ?', 'mcq', '["Le roi se meurt","La Cantatrice chauve","Rhinocéros","Les Chaises"]'::jsonb, 0, 'Le titre annonce le programme de la pièce.', 6),
    ('03716f15-46cd-55c6-91ce-4c9b37b71762'::uuid, 'ba7ea3af-f892-5617-ba6f-27a953f1cee0'::uuid, 'Le hors-scène affaiblit toujours l’effet produit par la mort.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il la rend souvent plus grande, en la confiant à l’imagination.', 7),
    ('c8569a26-0e25-5439-b23f-cc670e172616'::uuid, 'ba7ea3af-f892-5617-ba6f-27a953f1cee0'::uuid, 'Quel enjeu traverse le traitement de la mort réelle au théâtre contemporain ?', 'mcq', '["Ne pas transformer la mort d’autrui en spectacle","Rendre les scènes plus violentes","Respecter les trois unités","Éviter tout témoignage"]'::jsonb, 0, 'D’où le recours au chœur, au silence, à la liste de noms.', 8),
    ('272e2b6b-8736-5e1e-b33b-b60045f04749'::uuid, '2b7f78c9-1b91-528e-86cb-330c55089196'::uuid, 'Quelles règles encadrent la tragédie au XVIIe siècle ?', 'mcq', '["Les trois unités, la vraisemblance et la bienséance","Le mélange des genres","La liberté du lieu et du temps","L’usage exclusif de la prose"]'::jsonb, 0, 'Le classicisme fait de la contrainte une esthétique.', 1),
    ('7cc98816-f461-5648-a7a0-6949b99fa949'::uuid, '2b7f78c9-1b91-528e-86cb-330c55089196'::uuid, 'Quel auteur du XVIIe siècle est le maître de la comédie de mœurs et de caractère ?', 'mcq', '["Molière","Racine","Corneille","Rotrou"]'::jsonb, 0, 'Tartuffe, L’Avare, Le Misanthrope.', 2),
    ('1dc1c46f-fbc9-573c-a7fb-b5f79f76369c'::uuid, '2b7f78c9-1b91-528e-86cb-330c55089196'::uuid, 'Quelle pièce de Beaumarchais met une critique politique dans la bouche d’un valet ?', 'mcq', '["Le Mariage de Figaro","Le Jeu de l’amour et du hasard","Le Barbier de Séville uniquement","La Fausse Suivante"]'::jsonb, 0, 'Son monologue annonce les remises en cause révolutionnaires.', 3),
    ('42db43a9-e1c3-5d25-8dec-a69ebbe68303'::uuid, '2b7f78c9-1b91-528e-86cb-330c55089196'::uuid, 'Quel événement de 1830 symbolise le conflit entre classiques et romantiques ?', 'mcq', '["La bataille d’Hernani","La première de Tartuffe","La querelle du Cid","La création de Ruy Blas"]'::jsonb, 0, 'Une pièce de Hugo, un affrontement de salle.', 4),
    ('01798e60-97f1-5573-b357-b76b45a7f5c7'::uuid, '2b7f78c9-1b91-528e-86cb-330c55089196'::uuid, 'Qu’est-ce que la distanciation chez Brecht ?', 'mcq', '["Un ensemble de procédés qui empêchent l’identification pour faire réfléchir","Un éloignement du décor","Une mise en scène sans acteurs","Un jeu très réaliste"]'::jsonb, 0, 'Le spectateur doit juger, pas seulement ressentir.', 5),
    ('c1efe4b3-9edf-57d9-8ba4-7c8a68e6cb58'::uuid, '2b7f78c9-1b91-528e-86cb-330c55089196'::uuid, 'Quel courant du XXe siècle défait l’intrigue et le langage lui-même ?', 'mcq', '["Le théâtre de l’absurde","Le drame bourgeois","Le vaudeville","La commedia dell’arte"]'::jsonb, 0, 'Beckett et Ionesco en sont les figures majeures.', 6),
    ('1f9c6f47-b01f-54b3-ae5c-40d97266b8b3'::uuid, '2b7f78c9-1b91-528e-86cb-330c55089196'::uuid, 'Au XXe siècle, le metteur en scène devient un auteur à part entière.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa lecture du texte fait partie de l’œuvre.', 7),
    ('ca86e851-5d6d-5b1d-93e5-6d6ce58422e3'::uuid, '2b7f78c9-1b91-528e-86cb-330c55089196'::uuid, 'Quelles trois questions traversent le théâtre depuis quatre siècles ?', 'mcq', '["Que montre-t-on, à qui, depuis quel point de vue","Qui écrit, qui paie, qui joue","Combien d’actes, de scènes, de personnages","Quel décor, quel costume, quelle musique"]'::jsonb, 0, 'Elles suffisent à comparer deux pièces éloignées de trois siècles.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 283 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 283 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
